@startuml

class Well {
  + code : string
  + pollutionRate() : float
}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + yearOfInstallation : int
  + pollutionRate() : float
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

Well "*" -- "*" Company : extraction
(Well, Company) .. Extraction

Well "0..1" -- "0..1" GeographicalArea : locatedIn

@enduml

